               this.mos_item.mosachievementjoin.may = this.mos_item.mosachievementjoin.may > 0 ? this.mos_item.mosachievementjoin.may : this.targetAchivement('may', this.mos_item);
               this.mos_item.mosachievementjoin.june = this.mos_item.mosachievementjoin.june > 0 ? this.mos_item.mosachievementjoin.june : this.targetAchivement('june', this.mos_item);
               this.mos_item.mosachievementjoin.july = this.mos_item.mosachievementjoin.july > 0 ? this.mos_item.mosachievementjoin.july : this.targetAchivement('july', this.mos_item);
               this.mos_item.mosachievementjoin.august = this.mos_item.mosachievementjoin.august > 0 ? this.mos_item.mosachievementjoin.august : this.targetAchivement('august', this.mos_item);
               this.mos_item.mosachievementjoin.september = this.mos_item.mosachievementjoin.september > 0 ? this.mos_item.mosachievementjoin.september : this.targetAchivement('september', this.mos_item);
               this.mos_item.mosachievementjoin.october = this.mos_item.mosachievementjoin.october > 0 ? this.mos_item.mosachievementjoin.october : this.targetAchivement('october', this.mos_item);
               this.mos_item.mosachievementjoin.november = this.mos_item.mosachievementjoin.november > 0 ? this.mos_item.mosachievementjoin.november : this.targetAchivement('november', this.mos_item);
               this.mos_item.mosachievementjoin.december = this.mos_item.mosachievementjoin.december > 0 ? this.mos_item.mosachievementjoin.december : this.targetAchivement('december', this.mos_item);
