     targetAchivement(month, mos_item) {
       let target = 0;
       let achivement = 0;
       let myTarget = mos_item.mostargetjoin[month];
       mos_item.mos_kpi.forEach(kpi_mos => {
         kpi_mos.mosjoin.forEach(mos => {
           target += mos.mostargetjoin[month];
           achivement += mos.mosachievementjoin[month];
         });
       });
       let myAchivement = target > 0 && achivement > 0 ? ((achivement / target) * myTarget) : 0;
       return Number(myAchivement).toFixed(2);
       // if(type == 'target'){
       //   return target ;
       // }else if(type == 'achivement'){
       //   return achivement
       // }else{
       //   return 0 ; 
